<script setup lang="ts">import {computed} from 'vue';const props=defineProps<{page:number;totalCount:number|null;pageSize:number;disabled:boolean}>();defineEmits<{move:[page:number]}>();const pages=computed(()=>Math.max(1,Math.ceil((props.totalCount||0)/props.pageSize)));</script>
<template><nav class="pager" aria-label="ページ操作" data-field-id="SRC-031"><button :disabled="disabled||page<=1" @click="$emit('move',1)">先頭</button><button :disabled="disabled||page<=1" @click="$emit('move',page-1)">前へ</button><strong>{{page}} / {{pages}}</strong><button :disabled="disabled||page>=pages" @click="$emit('move',page+1)">次へ</button><button :disabled="disabled||page>=pages" @click="$emit('move',pages)">最後</button></nav></template>
